        pid=f'prototype_{i+1}'
        has_prior=any(math.hypot(*p)>prior.radius*math.cos(math.pi/prior.directions)-1e-6 for p in c['polygon'])
        prototypes[pid]=Prototype(pid,c['polygon'],c['members'],has_prior,c['constraints'])
